"""Create owned native dictionary cases; input fixture generated by Rust example."""
from pathlib import Path
import zipfile,json,copy,uuid
root=Path(__file__).resolve().parent
with zipfile.ZipFile(root/'combined-fixture/fixture.sketch') as z: files={n:z.read(n) for n in z.namelist()}
pagename=next(n for n in files if n.startswith('pages/') and n.endswith('.json'))
page=json.loads(files[pagename]);doc=json.loads(files['document.json'])
def walk(n):
 yield n
 for c in n.get('layers',[]):yield from walk(c)
for n in walk(page):
 n.pop('userInfo',None)
 if n.get('name') in ['Go next','Go back']:n['_class']='hotspot';n.pop('style',None)
 if n.get('name')=='stack-32':n['horizontalSizing']=2
 if n.get('name')=='stack-31':n['horizontalPins']=1
# Keep document resource receipts so the same font bytes are available to the portable renderer.
def save(name,p,d):
 f=dict(files);f[pagename]=json.dumps(p,separators=(',',':')).encode();f['document.json']=json.dumps(d,separators=(',',':')).encode()
 with zipfile.ZipFile(root/name,'w',zipfile.ZIP_DEFLATED) as z:
  for k,v in f.items():z.writestr(k,v)
save('native-input.sketch',page,doc)
master=next(n for n in page['layers'] if n.get('_class')=='symbolMaster')
lib=copy.deepcopy(page);lib['layers']=[copy.deepcopy(master)]
save('library-v1.sketch',lib,doc)
lib2=copy.deepcopy(lib);t=lib2['layers'][0]['layers'][0];t['attributedString']['string']='Updated source';t['attributedString']['attributes'][0]['length']=len('Updated source');t['attributedString']['attributes'][0]['attributes']['MSAttributedStringColorAttribute']={'_class':'color','red':.8,'green':.1,'blue':.2,'alpha':1}
save('library-v2.sketch',lib2,doc)
consumer=copy.deepcopy(page);consumer['layers']=[n for n in consumer['layers'] if n.get('_class')!='symbolMaster']
local=copy.deepcopy(master);mapping={n['do_objectID']:str(uuid.uuid5(uuid.NAMESPACE_URL,'local-sketch-'+n['do_objectID'])).upper() for n in walk(local)}
for n in walk(local):n['do_objectID']=mapping[n['do_objectID']]
for n in walk(consumer):
 if n.get('_class')=='symbolInstance':
  for v in n.get('overrideValues',[]):
   for old,new in mapping.items():v['overrideName']=v['overrideName'].replace(old,new)
cd=copy.deepcopy(doc);cd['do_objectID']='E04A0000-0000-4000-8000-000000000090';cd['foreignSymbols']=[{'_class':'MSImmutableForeignSymbol','libraryID':doc['do_objectID'],'symbolMaster':local,'originalMaster':copy.deepcopy(master),'remoteToLocalIDMap':mapping}]
save('foreign-consumer.sketch',consumer,cd)
(root/'fixture-identities.json').write_text(json.dumps({'nativeDocument':doc['do_objectID'],'symbol':master['symbolID'],'remoteToLocal':mapping},indent=2))
